def eulerian_num(n, m):
    if m < 0 or m >= n: return 1 if n == 0 and m == 0 else 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][0] = 1
        for j in range(1, min(i, m + 1)):
            dp[i][j] = (j + 1) * dp[i-1][j] + (i - j) * dp[i-1][j-1]
    return dp[n][m]

