def newman_prime(n):
    count = 0
    s_prev, s_curr = 1, 7
    while True:
        is_prime = s_curr > 1
        for i in range(2, int(s_curr**0.5) + 1):
            if s_curr % i == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
            if count == n:
                return s_curr
        s_prev, s_curr = s_curr, 6 * s_curr - s_prev

def get_total_number_of_sequences(m,n): 
	T=[[0 for i in range(n+1)] for i in range(m+1)] 
	for i in range(m+1): 
		for j in range(n+1): 
			if i==0 or j==0: 
				T[i][j]=0
			elif j==1: 
				T[i][j]=i 
			else: 
				T[i][j]=T[i-1][j]+T[i//2][j-1] 
	return T[m][n]

